  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <div
      {...profileScopeAttributes("service")}
      className="flex flex-col gap-6 bg-background font-sans text-foreground"
    >
      <ShopNav />
      {children}
    </div>
  )
}

