import type { Metadata } from "next"
import { notFound } from "next/navigation"

import { Badge } from "@/components/ui/badge"
import { Separator } from "@/components/ui/separator"
import { ProductGallery } from "@/app/templates/shop/_components/product-gallery"
import { ProductOptions } from "@/app/templates/shop/_components/product-options"
import { ReviewSummaryPanel } from "@/app/templates/shop/_components/review-summary"
import { categoryOf, discountPercent, getProduct, listProductIds } from "@/app/templates/shop/_lib/data"

interface ProductPageProps {
  params: Promise<{ id: string }>
}

export function generateStaticParams() {
  return listProductIds().map((id) => ({ id }))
}

export async function generateMetadata({ params }: Readonly<ProductPageProps>): Promise<Metadata> {
  const { id } = await params
  const product = getProduct(id)
  return { title: product ? `${product.name} · Shop 템플릿` : "상품 상세 · Shop 템플릿" }
}

/** #30 상품상세 — carousel(이미지) + 옵션·수량 + 리뷰 요약. */
export default async function ShopProductPage({ params }: Readonly<ProductPageProps>) {
  const { id } = await params
  const product = getProduct(id)

  if (!product) {
    notFound()
  }

  const category = categoryOf(product.category)
  const percentOff = discountPercent(product)

  return (
    <div className="flex flex-col gap-10 pb-8">
      <div className="grid grid-cols-1 gap-8 lg:grid-cols-2">
        <ProductGallery category={product.category} slideCount={product.gallerySlides} />

        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <div className="flex flex-wrap items-center gap-1.5">
              <Badge variant="outline" className="gap-1 text-[10px]">
                <category.icon size={11} weight="regular" />
                {category.label}
              </Badge>
              {product.badges.map((badge) => (
                <Badge key={badge} variant="secondary" className="text-[10px]">
                  {badge}
                </Badge>
              ))}
            </div>
            <h1 className="text-2xl font-semibold tracking-tight">{product.name}</h1>
            <p className="text-sm text-muted-foreground">{product.shortDescription}</p>
          </div>

          <div className="flex items-baseline gap-2">
            {percentOff !== undefined && product.originalPrice && (
              <>
                <span className="text-lg font-semibold text-destructive">{percentOff}%</span>
                <span className="text-base text-muted-foreground line-through">
                  {product.originalPrice.toLocaleString()}원
                </span>
              </>
            )}
            <span className="text-3xl font-bold tabular-nums text-foreground">
              {product.price.toLocaleString()}원
            </span>
          </div>

          <Separator />

          <ProductOptions product={product} />
        </div>
      </div>

      <Separator />

      <section className="flex flex-col gap-3">
        <h2 className="text-lg font-semibold tracking-tight">상품 설명</h2>
        <p className="max-w-prose text-sm text-pretty text-muted-foreground">{product.description}</p>
      </section>

      <Separator />

      <section className="flex flex-col gap-3">
        <h2 className="text-lg font-semibold tracking-tight">리뷰</h2>
        <ReviewSummaryPanel reviews={product.reviews} />
      </section>
    </div>
  )
}

"use client"

import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from "@/components/ui/carousel"
import { ProductVisual } from "@/app/templates/shop/_components/product-visual"
import type { CategoryKey } from "@/app/templates/shop/_lib/data"

interface ProductGalleryProps {
  category: CategoryKey
  slideCount: number
}

/** 상품상세 이미지 캐러셀 — 슬라이드마다 ProductVisual을 다른 시드로 렌더한다. */
export function ProductGallery({ category, slideCount }: Readonly<ProductGalleryProps>) {
  const slides = Array.from({ length: slideCount }, (_, i) => i)

  return (
    <Carousel className="w-full">
      <CarouselContent>
        {slides.map((seed) => (
          <CarouselItem key={seed}>
            <ProductVisual category={category} seed={seed} />
          </CarouselItem>
        ))}
      </CarouselContent>
      {slideCount > 1 && (
        <>
          <CarouselPrevious />
          <CarouselNext />
        </>
      )}
    </Carousel>
  )
}

"use client"

import { useMemo, useState } from "react"

import { cn } from "@/lib/utils"
import { ProductCard } from "@/app/templates/shop/_components/product-card"
import { CATEGORIES, PRODUCTS, type CategoryKey } from "@/app/templates/shop/_lib/data"

/**
 * 카테고리 faceted 필터(components/patterns/faceted-filter 기법) + 상품 그리드.
 * 모바일 1열 → 데스크톱 다열로 처음부터 반응형이다.
 */
export function ProductGrid() {
  const [category, setCategory] = useState<CategoryKey | "">("")

  const filtered = useMemo(
    () => (category === "" ? PRODUCTS : PRODUCTS.filter((p) => p.category === category)),
    [category],
  )

  return (
    <section id="product-grid" className="flex flex-col gap-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h2 className="text-lg font-semibold tracking-tight">전체 상품</h2>
        <div className="flex flex-wrap items-center gap-1.5 overflow-x-auto pb-1" role="group" aria-label="카테고리 필터">
          <FacetChip active={category === ""} onClick={() => setCategory("")}>
            전체
            <CountBadge active={category === ""}>{PRODUCTS.length}</CountBadge>
          </FacetChip>
          {CATEGORIES.map((c) => {
            const Icon = c.icon
            const count = PRODUCTS.filter((p) => p.category === c.key).length
            return (
              <FacetChip key={c.key} active={category === c.key} onClick={() => setCategory(c.key)}>
                <Icon size={13} weight={category === c.key ? "fill" : "regular"} />
                {c.label}
                <CountBadge active={category === c.key}>{count}</CountBadge>
              </FacetChip>
            )
          })}
        </div>
      </div>

      {filtered.length === 0 ? (
        <p className="rounded-lg border border-dashed border-border py-12 text-center text-sm text-muted-foreground">
          해당 카테고리에 상품이 없습니다.
        </p>
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {filtered.map((product) => (
            <ProductCard key={product.id} product={product} />
          ))}
        </div>
      )}
    </section>
  )
}

function FacetChip({
  active,
  onClick,
  children,
}: Readonly<{ active: boolean; onClick: () => void; children: React.ReactNode }>) {
  return (
    <button
      type="button"
      aria-pressed={active}
      onClick={onClick}
      className={cn(
        "inline-flex shrink-0 items-center gap-1 rounded-full border px-3 py-1 text-xs font-medium transition-colors",
        active
          ? "border-transparent bg-primary text-primary-foreground"
          : "border-border bg-card text-foreground hover:bg-accent",
      )}
    >
      {children}
    </button>
  )
}

function CountBadge({ active, children }: Readonly<{ active: boolean; children: React.ReactNode }>) {
  return (
    <span className={cn("font-mono text-[10px]", active ? "text-primary-foreground/80" : "text-muted-foreground")}>
      {children}
    </span>
  )
}

"use client"

import { useMemo, useState } from "react"
import { MinusIcon, PlusIcon, ShoppingCartSimpleIcon } from "@phosphor-icons/react/dist/ssr"

import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import type { Product } from "@/app/templates/shop/_lib/data"

/** 옵션 선택 + 수량 조절 + 담기 CTA. 데모용 로컬 상태만 관리하고 실제 장바구니에 반영하지는 않는다. */
export function ProductOptions({ product }: Readonly<{ product: Product }>) {
  const [selected, setSelected] = useState<Record<string, string>>(() =>
    Object.fromEntries(product.options.map((option) => [option.label, option.values[0]])),
  )
  const [quantity, setQuantity] = useState(1)
  const soldOut = product.stock === 0

  const totalPrice = useMemo(() => product.price * quantity, [product.price, quantity])

  function decrement() {
    setQuantity((q) => Math.max(1, q - 1))
  }

  function increment() {
    setQuantity((q) => Math.min(product.stock || 1, q + 1))
  }

  return (
    <div className="flex flex-col gap-5">
      {product.options.map((option) => (
        <fieldset key={option.label} className="flex flex-col gap-2">
          <legend className="text-sm font-medium text-foreground">{option.label}</legend>
          <RadioGroup
            className="grid-flow-col auto-cols-max gap-2"
            value={selected[option.label]}
            onValueChange={(value) => setSelected((prev) => ({ ...prev, [option.label]: value }))}
          >
            {option.values.map((value) => {
              const id = `${option.label}-${value}`
              const active = selected[option.label] === value
              return (
                <Label
                  key={value}
                  htmlFor={id}
                  className="cursor-pointer rounded-md border border-input px-3 py-1.5 text-sm has-data-checked:border-primary has-data-checked:bg-primary has-data-checked:text-primary-foreground"
                >
                  <RadioGroupItem id={id} value={value} className="sr-only" />
                  {value}
                  <span className="sr-only">{active ? " (선택됨)" : ""}</span>
                </Label>
              )
            })}
          </RadioGroup>
        </fieldset>
      ))}

      <div className="flex flex-col gap-2">
        <Label htmlFor="quantity" className="text-sm font-medium text-foreground">
          수량
        </Label>
        <div className="flex w-fit items-center gap-1 rounded-lg border border-input p-1">
          <Button type="button" variant="ghost" size="icon-sm" onClick={decrement} disabled={quantity <= 1 || soldOut}>
            <MinusIcon size={14} />
            <span className="sr-only">수량 감소</span>
          </Button>
          <span id="quantity" className="w-8 text-center text-sm font-medium tabular-nums" aria-live="polite">
            {quantity}
          </span>
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            onClick={increment}
            disabled={soldOut || quantity >= product.stock}
          >
            <PlusIcon size={14} />
            <span className="sr-only">수량 증가</span>
          </Button>
        </div>
        <p className="text-xs text-muted-foreground">
          {soldOut ? "품절된 상품입니다." : `재고 ${product.stock.toLocaleString()}개 남음`}
        </p>
      </div>

      <div className="flex items-center justify-between border-t border-border pt-4">
        <div>
          <p className="text-xs text-muted-foreground">총 상품 금액</p>
          <p className="text-xl font-bold tabular-nums text-foreground">{totalPrice.toLocaleString()}원</p>
        </div>
        <Button type="button" size="lg" disabled={soldOut}>
          <ShoppingCartSimpleIcon size={16} weight="bold" />
          {soldOut ? "품절" : "장바구니 담기"}
        </Button>
      </div>
    </div>
  )
}

import { cn } from "@/lib/utils"
import { categoryOf, type CategoryKey } from "@/app/templates/shop/_lib/data"

interface ProductVisualProps {
  category: CategoryKey
  /** 같은 카테고리 안에서도 슬라이드마다 다른 각도/위치를 만들기 위한 시드. */
  seed?: number
  className?: string
}

/**
 * 상품 이미지 대체용 CSS 그라디언트 + 도형 + 카테고리 아이콘 비주얼.
 * 폐쇄망 대응 규칙(상품이미지 외부 URL 금지)에 따라 실제 사진 대신 이
 * 컴포넌트로 카드/캐러셀 슬라이드를 채운다 — 하드코딩 색 없이 카테고리별
 * chart 토큰 그라디언트만 사용한다.
 */
export function ProductVisual({ category, seed = 0, className }: Readonly<ProductVisualProps>) {
  const { icon: Icon, toneClass } = categoryOf(category)
  const rotate = ((seed * 37) % 24) - 12
  const offsetX = ((seed * 19) % 20) - 10
  const offsetY = ((seed * 11) % 20) - 10

  return (
    <div
      className={cn(
        "relative flex aspect-square w-full items-center justify-center overflow-hidden rounded-lg bg-muted",
        className,
      )}
    >
      <div
        aria-hidden
        className={cn("absolute size-[70%] rounded-[38%] bg-gradient-to-br blur-md", toneClass)}
        style={{ transform: `rotate(${rotate}deg) translate(${offsetX}%, ${offsetY}%)` }}
      />
      <div
        aria-hidden
        className={cn("absolute size-[45%] rounded-full bg-gradient-to-tr opacity-70", toneClass)}
        style={{ transform: `translate(${-offsetX * 0.6}%, ${-offsetY * 0.6}%)` }}
      />
      <Icon size={40} weight="duotone" className="relative z-10 text-foreground/70" />
    </div>
  )
}

import { StarIcon } from "@phosphor-icons/react/dist/ssr"

import { Progress } from "@/components/ui/progress"
import type { ReviewSummary } from "@/app/templates/shop/_lib/data"

/** 리뷰 요약 — 평균 별점 + 별점별 분포 막대. */
export function ReviewSummaryPanel({ reviews }: Readonly<{ reviews: ReviewSummary }>) {
  return (
    <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:gap-8">
      <div className="flex flex-col items-center gap-1">
        <p className="text-3xl font-bold tabular-nums text-foreground">{reviews.average.toFixed(1)}</p>
        <div className="flex items-center gap-0.5">
          {Array.from({ length: 5 }, (_, i) => (
            <StarIcon
              key={i}
              size={14}
              weight="fill"
              className={i < Math.round(reviews.average) ? "text-warning" : "text-muted"}
            />
          ))}
        </div>
        <p className="text-xs text-muted-foreground">리뷰 {reviews.count.toLocaleString()}개</p>
      </div>

      <div className="flex flex-1 flex-col gap-1.5">
        {reviews.breakdown.map((percent, index) => {
          const star = 5 - index
          return (
            <div key={star} className="flex items-center gap-2">
              <span className="w-8 shrink-0 text-xs text-muted-foreground">{star}점</span>
              <Progress value={percent} className="h-1.5" />
              <span className="w-9 shrink-0 text-right text-xs tabular-nums text-muted-foreground">{percent}%</span>
            </div>
          )
        })}
      </div>
    </div>
  )
}

"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { ShoppingCartSimpleIcon, StorefrontIcon } from "@phosphor-icons/react/dist/ssr"

import { cn } from "@/lib/utils"
import { CART_LINES } from "@/app/templates/shop/_lib/data"

const TABS = [
  { href: "/templates/shop", label: "스토어", icon: StorefrontIcon },
  { href: "/templates/shop/cart", label: "장바구니", icon: ShoppingCartSimpleIcon },
] as const

/**
 * Shop 템플릿 페이지(스토어/장바구니) 간 이동 탭.
 * 템플릿 자체 데모용 내비게이션이며, 사이드바(components/site-sidebar.tsx)와는
 * 별개다 — 그쪽은 상위 배선이라 이 이슈 범위에서 건드리지 않는다.
 */
export function ShopNav() {
  const pathname = usePathname()
  const cartCount = CART_LINES.reduce((sum, line) => sum + line.quantity, 0)

  return (
    <nav
      aria-label="Shop 템플릿 페이지"
      className="flex w-fit items-center gap-1 rounded-lg border border-border bg-card p-1"
    >
      {TABS.map((tab) => {
        const active = pathname === tab.href
        const Icon = tab.icon
        return (
          <Link
            key={tab.href}
            href={tab.href}
            aria-current={active ? "page" : undefined}
            className={cn(
              "flex items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors",
              active
                ? "bg-primary text-primary-foreground"
                : "text-muted-foreground hover:bg-muted hover:text-foreground",
            )}
          >
            <Icon size={16} weight={active ? "duotone" : "regular"} />
            {tab.label}
            {tab.href === "/templates/shop/cart" && cartCount > 0 && (
              <span
                className={cn(
                  "flex h-4 min-w-4 items-center justify-center rounded-full px-1 text-[10px] font-semibold tabular-nums",
                  active ? "bg-primary-foreground text-primary" : "bg-primary text-primary-foreground",
                )}
              >
                {cartCount}
              </span>
            )}
          </Link>
        )
      })}
    </nav>
  )
}

